<?php
declare(strict_types=1);
// Colors match TreeApp.getTreeMarkerColor in markers.js.
function qxPalette(string $field):array{return $field==='longevity'?['a'=>'#2e7d32','b'=>'#ef7d00','c'=>'#c62828']:['1'=>'#2e7d32','2'=>'#1976d2','3'=>'#d6aa00','4'=>'#ef7d00','5'=>'#c62828'];}
function qxSrs(int $epsg):string{return $epsg===4326?'<srs><spatialrefsys nativeFormat="Wkt"><wkt>GEOGCRS["WGS 84",ENSEMBLE["World Geodetic System 1984 ensemble",MEMBER["World Geodetic System 1984 (Transit)"],MEMBER["World Geodetic System 1984 (G730)"],MEMBER["World Geodetic System 1984 (G873)"],MEMBER["World Geodetic System 1984 (G1150)"],MEMBER["World Geodetic System 1984 (G1674)"],MEMBER["World Geodetic System 1984 (G1762)"],MEMBER["World Geodetic System 1984 (G2139)"],ELLIPSOID["WGS 84",6378137,298.257223563,LENGTHUNIT["metre",1]],ENSEMBLEACCURACY[2.0]],PRIMEM["Greenwich",0,ANGLEUNIT["degree",0.0174532925199433]],CS[ellipsoidal,2],AXIS["geodetic latitude (Lat)",north,ORDER[1],ANGLEUNIT["degree",0.0174532925199433]],AXIS["geodetic longitude (Lon)",east,ORDER[2],ANGLEUNIT["degree",0.0174532925199433]],USAGE[SCOPE["Horizontal component of 3D system."],AREA["World."],BBOX[-90,-180,90,180]],ID["EPSG",4326]]</wkt><proj4>+proj=longlat +datum=WGS84 +no_defs</proj4><srsid>3452</srsid><srid>4326</srid><authid>EPSG:4326</authid><description>WGS 84</description><projectionacronym>longlat</projectionacronym><ellipsoidacronym>EPSG:7030</ellipsoidacronym><geographicflag>true</geographicflag></spatialrefsys></srs>':'<srs><spatialrefsys nativeFormat="Wkt"><wkt>PROJCRS["WGS 84 / Pseudo-Mercator",BASEGEOGCRS["WGS 84",ENSEMBLE["World Geodetic System 1984 ensemble",MEMBER["World Geodetic System 1984 (Transit)"],MEMBER["World Geodetic System 1984 (G730)"],MEMBER["World Geodetic System 1984 (G873)"],MEMBER["World Geodetic System 1984 (G1150)"],MEMBER["World Geodetic System 1984 (G1674)"],MEMBER["World Geodetic System 1984 (G1762)"],MEMBER["World Geodetic System 1984 (G2139)"],ELLIPSOID["WGS 84",6378137,298.257223563,LENGTHUNIT["metre",1]],ENSEMBLEACCURACY[2.0]],PRIMEM["Greenwich",0,ANGLEUNIT["degree",0.0174532925199433]],ID["EPSG",4326]],CONVERSION["Popular Visualisation Pseudo-Mercator",METHOD["Popular Visualisation Pseudo Mercator",ID["EPSG",1024]],PARAMETER["Latitude of natural origin",0,ANGLEUNIT["degree",0.0174532925199433],ID["EPSG",8801]],PARAMETER["Longitude of natural origin",0,ANGLEUNIT["degree",0.0174532925199433],ID["EPSG",8802]],PARAMETER["False easting",0,LENGTHUNIT["metre",1],ID["EPSG",8806]],PARAMETER["False northing",0,LENGTHUNIT["metre",1],ID["EPSG",8807]]],CS[Cartesian,2],AXIS["easting (X)",east,ORDER[1],LENGTHUNIT["metre",1]],AXIS["northing (Y)",north,ORDER[2],LENGTHUNIT["metre",1]],USAGE[SCOPE["Web mapping and visualisation."],AREA["World between 85.06°S and 85.06°N."],BBOX[-85.06,-180,85.06,180]],ID["EPSG",3857]]</wkt><proj4>+proj=merc +a=6378137 +b=6378137 +lat_ts=0 +lon_0=0 +x_0=0 +y_0=0 +k=1 +units=m +nadgrids=@null +wktext +no_defs</proj4><srsid>3857</srsid><srid>3857</srid><authid>EPSG:3857</authid><description>WGS 84 / Pseudo-Mercator</description><projectionacronym>merc</projectionacronym><ellipsoidacronym>EPSG:7030</ellipsoidacronym><geographicflag>false</geographicflag></spatialrefsys></srs>';}
function qxProps(array $props):string{$out='';foreach($props as $k=>$v)$out.='<prop k="'.exXml($k).'" v="'.exXml($v).'"/>';return $out;}
function qxSymbol(string $name,string $shape,string $color,bool $polygon=false,string $field=''):string{
 $props=$polygon?['color'=>$color,'outline_color'=>'#35623e','outline_style'=>'solid','outline_width'=>'0.25','outline_width_unit'=>'MM','style'=>'solid']:['name'=>$shape,'color'=>$color,'outline_color'=>'#26392d','outline_width'=>'0.25','outline_width_unit'=>'MM','size'=>'2','size_unit'=>'RenderMetersInMapUnits','size_map_unit_scale'=>'3x:0,0,1,2,0,0','scale_method'=>'diameter','horizontal_anchor_point'=>'1','vertical_anchor_point'=>'1'];
 return '<symbol name="'.exXml($name).'" type="'.($polygon?'fill':'marker').'" alpha="1" clip_to_extent="1"><layer class="'.($polygon?'SimpleFill':'SimpleMarker').'" locked="0" pass="0">'.qxProps($props).($polygon?'':qxSizeProperty($field)).'</layer></symbol>';
}
function qxRenderer(string $field):string{
 $categories='';$symbols='';$i=0;
 foreach(['angiospermae'=>['circle','Krytosemenné'],'gymnospermae'=>['triangle','Nahosemenné'],''=>['diamond','Neurčeno']] as $value=>[$shape,$label]){
  $categories.='<category value="'.exXml($value).'" label="'.$label.'" symbol="'.$i.'" render="true" type="string"/>';
  $symbols.=qxSymbol((string)$i,$shape,'#c8c8c8',false,$field);$i++;
 }
 return '<renderer-v2 type="categorizedSymbol" attr="'.exXml("lower(trim(coalesce(\"angio_gymno\",'')))").'" symbollevels="0"><categories>'.$categories.'</categories><symbols>'.$symbols.'</symbols></renderer-v2>';
}
function qxLabels(string $field):string{return '<labeling type="simple"><settings><text-style fieldName="'.exXml($field).'" isExpression="0" fontFamily="Sans Serif" fontSize="9" fontSizeUnit="Point" textColor="30,44,35,255"><text-buffer bufferDraw="1" bufferSize="1" bufferSizeUnits="MM" bufferColor="255,255,255,255"/></text-style><placement placement="0" dist="2"/><rendering scaleVisibility="1" scaleMin="1" scaleMax="10000"/></settings></labeling>';}
function qxLayer(string $id,string $name,string $table,string $geometry,string $renderer='',string $label='',array $columns=[]):string{
 $photo=str_starts_with($table,'foto_');
 $form=$photo?'<fieldConfiguration><field name="export_path"><editWidget type="ExternalResource"><config><Option type="Map"><Option name="DocumentViewer" type="int" value="1"/><Option name="DocumentViewerHeight" type="int" value="260"/><Option name="DocumentViewerWidth" type="int" value="360"/><Option name="RelativeStorage" type="int" value="1"/><Option name="FileWidget" type="bool" value="true"/></Option></config></editWidget></field></fieldConfiguration>':'';
 $extra='';$layout='<editorlayout>generatedlayout</editorlayout>';
 if($photo){$layout='<editorlayout>tablayout</editorlayout><attributeEditorForm><attributeEditorField name="export_path" showLabel="0"/><attributeEditorField name="note" showLabel="1"/><attributeEditorField name="export_status" showLabel="1"/></attributeEditorForm>';$extra='<aliases><alias field="note" name="Popisek fotografie"/><alias field="export_status" name="Stav exportu"/></aliases>';}
 if(in_array($table,['stromy','plochy'],true)){
  $form='<fieldConfiguration><field name="foto_hlavni"><editWidget type="ExternalResource"><config><Option type="Map"><Option name="DocumentViewer" type="int" value="1"/><Option name="DocumentViewerHeight" type="int" value="260"/><Option name="DocumentViewerWidth" type="int" value="360"/><Option name="RelativeStorage" type="int" value="1"/><Option name="FileWidget" type="bool" value="true"/></Option></config></editWidget></field><field name="fotogalerie"><editWidget type="ExternalResource"><config><Option type="Map"><Option name="RelativeStorage" type="int" value="1"/><Option name="FileWidget" type="bool" value="true"/></Option></config></editWidget></field></fieldConfiguration>';
  if($columns){$ordered=array_values(array_unique(array_merge(['foto_hlavni',$table==='stromy'?'usr_id':'code',$table==='stromy'?'species':'name','czech','fotogalerie'],$columns)));$elements='';foreach($ordered as $key)if(in_array($key,$columns,true)&&!in_array($key,['geom','fid'],true))$elements.='<attributeEditorField name="'.exXml($key).'" index="'.array_search($key,$columns,true).'" showLabel="1"/>';$layout='<editorlayout>tablayout</editorlayout><attributeEditorForm>'.$elements.'<attributeEditorRelation name="Fotografie" relation="'.($table==='plochy'?'foto_plochy':($id==='svm_longevity'?'foto_longevity':'foto_stability')).'" showLabel="1" forceSuppressFormPopup="0"/>' .'</attributeEditorForm>';}
  $action="file:///[% @project_folder || '/' || \"fotogalerie\" %]";
  $tip='<b>Fotografie objektu</b><br><a href="'.$action.'">Otevřít všechny fotografie</a><br><img style="max-width:280px;max-height:220px" src="file:///[% @project_folder || \'/\' || "foto_hlavni" %]">';
  $extra='<attributeactions><actionsetting type="5" name="Fotografie objektu" shortTitle="Fotografie" action="'.exXml($action).'" capture="0" notificationMessage="" isEnabledOnlyWhenEditable="0" id="{716b525c-36c6-47a6-81f7-f793db924653}"><actionScope id="Feature"/><actionScope id="Canvas"/></actionsetting></attributeactions><mapTip enabled="1">'.exXml($tip).'</mapTip><aliases><alias field="usr_id" name="Číslo stromu"/><alias field="code" name="Číslo plochy"/><alias field="species" name="Druh"/><alias field="czech" name="Český název"/><alias field="foto_hlavni" name="Hlavní fotografie"/><alias field="fotogalerie" name="Galerie fotografií"/></aliases>';
 }
 return '<maplayer type="vector" geometry="'.$geometry.'" hasScaleBasedVisibilityFlag="0" labelsEnabled="'.($label!==''?'1':'0').'" simplifyDrawingHints="0"><id>'.$id.'</id><datasource>./projekt.gpkg|layername='.$table.'</datasource><layername>'.exXml($name).'</layername>'.qxSrs(4326).'<provider encoding="UTF-8">ogr</provider><displayfield>'.($photo?'original_name':($table==='plochy'?'code':'usr_id')).'</displayfield>'.$renderer.($label!==''?qxLabels($label):'').$form.$extra.'<editform tolerant="1"/>'.$layout.'</maplayer>';
}
function qxWms(string $id,string $name,string $url,string $layers):string{
 $source=str_replace(['%3A','%2F'],[':','/'],http_build_query(['contextualWMSLegend'=>0,'crs'=>'EPSG:3857','format'=>'image/png','layers'=>$layers,'styles'=>'','url'=>$url],'','&',PHP_QUERY_RFC3986));
 return '<maplayer type="raster" hasScaleBasedVisibilityFlag="0"><id>'.$id.'</id><datasource>'.exXml($source).'</datasource><layername>'.exXml($name).'</layername>'.qxSrs(3857).'<provider>wms</provider><rasterrenderer type="singlebandcolordata" band="1" opacity="1" alphaBand="-1"/></maplayer>';
}
function qxTree(string $id,string $name,bool $checked=true):string{return '<layer-tree-layer id="'.$id.'" name="'.exXml($name).'" checked="'.($checked?'Qt::Checked':'Qt::Unchecked').'" expanded="1"/>';}
function qxExtent(array $geometries):array{
 $points=[];$walk=function($a)use(&$walk,&$points){if(!is_array($a))return;if(count($a)>=2&&is_numeric($a[0]??null)&&is_numeric($a[1]??null)){if(abs((float)$a[0])<=180&&abs((float)$a[1])<=85)$points[]=[6378137*deg2rad((float)$a[0]),6378137*log(tan(M_PI/4+deg2rad((float)$a[1])/2))];}else foreach($a as $v)$walk($v);};foreach($geometries as $g)if($g)$walk($g['coordinates']);
 if(!$points)return [1300000,6100000,2150000,6650000];$xs=array_column($points,0);$ys=array_column($points,1);$pad=max(30,(max($xs)-min($xs))*.1,(max($ys)-min($ys))*.1);return [min($xs)-$pad,min($ys)-$pad,max($xs)+$pad,max($ys)+$pad];
}
function qxProject(string $path,string $title,array $geometries,bool $haveTrees,bool $haveAreas,?string $gpkgPath=null):void{
 $layers='';$tree='';$relations='';$columns=[];$gpkg=$gpkgPath??dirname($path).'/projekt.gpkg';
 if(is_file($gpkg)){$db=new SQLite3($gpkg,SQLITE3_OPEN_READONLY);foreach(['stromy','plochy'] as $table){$columns[$table]=[];$r=$db->query('PRAGMA table_info('.$table.')');while($row=$r->fetchArray(SQLITE3_ASSOC))if($row['name']!=='geom')$columns[$table][]=$row['name'];}$db->close();}

 if($haveTrees){$tree.='<layer-tree-group name="Stromy – barvení (zapněte jednu variantu)" checked="Qt::Checked" expanded="1" mutually-exclusive="1" mutually-exclusive-child="0">';
 foreach(['longevity'=>'Perspektiva','stability'=>'Stabilita'] as $field=>$label){$id='svm_'.$field;$name='Stromy – '.$label;$tree.=qxTree($id,$name,$field==='longevity');$layers.=qxLayer($id,$name,'stromy','Point',qxRenderer($field),'usr_id',$columns['stromy']??[]);$relations.='<relation id="foto_'.$field.'" name="Fotografie stromu" referencingLayer="svm_foto_stromy" referencedLayer="'.$id.'" strength="Association"><fieldRef referencingField="object_code" referencedField="usr_id"/></relation>';}$tree.='</layer-tree-group>';
 $tree.=qxTree('svm_koruny_layer','Koruny – kruhový průmět podle šířky');$layers.=qxLayer('svm_koruny_layer','Koruny – kruhový průmět podle šířky','koruny','Polygon','<renderer-v2 type="singleSymbol"><symbols>'.qxSymbol('0','','80,140,90,45',true).'</symbols></renderer-v2>');
 }
 if($haveAreas){$tree.=qxTree('svm_plochy_layer','Plochy');$layers.=qxLayer('svm_plochy_layer','Plochy','plochy','Polygon','<renderer-v2 type="singleSymbol"><symbols>'.qxSymbol('0','','80,130,90,55',true).'</symbols></renderer-v2>','code',$columns['plochy']??[]);$relations.='<relation id="foto_plochy" name="Fotografie plochy" referencingLayer="svm_foto_plochy" referencedLayer="svm_plochy_layer" strength="Association"><fieldRef referencingField="object_code" referencedField="code"/></relation>';}
 $tree.='<layer-tree-group name="Fotografie – přiřazovací tabulky" checked="Qt::Checked" expanded="0">';foreach(['stromy'=>$haveTrees,'plochy'=>$haveAreas] as $kind=>$has)if($has){$tree.=qxTree('svm_foto_'.$kind,'Fotografie – '.$kind);$layers.=qxLayer('svm_foto_'.$kind,'Fotografie – '.$kind,'foto_'.$kind,'NoGeometry');}$tree.='</layer-tree-group>';
 $tree.=qxTree('svm_katastr_layer','Katastrální mapa ČÚZK',false);$layers.=qxWms('svm_katastr_layer','Katastrální mapa ČÚZK','https://services.cuzk.gov.cz/wms/local-KM-wms.asp','KN');
 $tree.='<layer-tree-group name="Podklady ČÚZK (online)" checked="Qt::Checked" expanded="1" mutually-exclusive="1" mutually-exclusive-child="0">';foreach([['ztm10','ZTM 10','https://ags.cuzk.gov.cz/arcgis1/services/ZTM/ZTM10/MapServer/WMSServer'],['ortofoto','Ortofoto','https://ags.cuzk.gov.cz/arcgis1/services/ORTOFOTO/MapServer/WMSServer']] as [$id,$label,$url]){$tree.=qxTree('svm_wms_'.$id,$label.' ČÚZK',$id==='ztm10');$layers.=qxWms('svm_wms_'.$id,$label.' ČÚZK',$url,'0');}$tree.='</layer-tree-group>';
 [$xmin,$ymin,$xmax,$ymax]=qxExtent($geometries);$extent="<extent><xmin>$xmin</xmin><ymin>$ymin</ymin><xmax>$xmax</xmax><ymax>$ymax</ymax></extent>";
 $xml='<?xml version="1.0" encoding="UTF-8"?><qgis version="3.34.0" projectname="'.exXml($title).'"><title>'.exXml($title).'</title><homePath path=""/><projectCrs>'.substr(qxSrs(3857),5,-6).'</projectCrs><layer-tree-group name="" checked="Qt::Checked" expanded="1">'.$tree.'</layer-tree-group><projectlayers>'.$layers.'</projectlayers><relations>'.$relations.'</relations><ProjectViewSettings><DefaultViewExtent xmin="'.$xmin.'" ymin="'.$ymin.'" xmax="'.$xmax.'" ymax="'.$ymax.'">'.substr(qxSrs(3857),5,-6).'</DefaultViewExtent></ProjectViewSettings><mapcanvas><units>meters</units>'.$extent.'<rotation>0</rotation><destinationsrs>'.substr(qxSrs(3857),5,-6).'</destinationsrs><rendermaptile>0</rendermaptile></mapcanvas><properties><SpatialRefSys><ProjectionsEnabled type="int">1</ProjectionsEnabled></SpatialRefSys><Paths><Absolute type="bool">false</Absolute></Paths></properties></qgis>';
 $doc=new DOMDocument();if(!$doc->loadXML($xml,LIBXML_NONET))throw new RuntimeException('Neplatný projekt QGIS.');$zip=new ZipArchive();if($zip->open($path,ZipArchive::CREATE|ZipArchive::OVERWRITE)!==true)throw new RuntimeException('QGZ open');$zip->addFromString('projekt.qgs',$xml);if(!$zip->close())throw new RuntimeException('QGZ close');
}
function qxCrowns(array $trees,array $geometries):array{
 $rows=[];$polygons=[];foreach($trees as $i=>$r){$width=$r['spread_m']??null;$g=$geometries[$i]??null;if(!$g||!is_numeric($width)||!is_finite((float)$width)||$width<=0||$width>200)continue;[$lon,$lat]=$g['coordinates'];if(abs($lat)>85)continue;$ring=[];for($j=0;$j<=48;$j++){$angle=2*M_PI*($j%48)/48;$ring[]=[(float)$lon+rad2deg(cos($angle)*$width/2/(6378137*cos(deg2rad($lat)))),(float)$lat+rad2deg(sin($angle)*$width/2/6378137)];}$rows[]=['usr_id'=>$r['usr_id']??null,'spread_m'=>$width];$polygons[]=['type'=>'Polygon','coordinates'=>[$ring]];}return [$rows,$polygons];
}
function qxPhotoTables(string $path,array $photos):void{
 $db=new SQLite3($path);$db->enableExceptions(true);$db->exec('BEGIN');try{foreach(['stromy'=>'strom','plochy'=>'plocha'] as $table=>$kind){$name='foto_'.$table;$db->exec('CREATE TABLE '.$name.' (fid INTEGER PRIMARY KEY,object_code TEXT NOT NULL,original_name TEXT,note TEXT,export_path TEXT,export_status TEXT)');$db->exec('CREATE INDEX '.$name.'_object ON '.$name.'(object_code)');$s=$db->prepare("INSERT INTO gpkg_contents(table_name,data_type,identifier,description) VALUES(?,'attributes',?,'Fotografie objektů')");$s->bindValue(1,$name);$s->bindValue(2,$name);$s->execute();$s=$db->prepare('INSERT INTO '.$name.'(object_code,original_name,note,export_path,export_status) VALUES(?,?,?,?,?)');foreach($photos as $row){if($row['object_type']!==$kind)continue;foreach(['object_code','original_name','note','export_path','export_status'] as $i=>$key){$value=$key==='export_path'&&$row['export_status']!=='zahrnuto'?null:$row[$key];$s->bindValue($i+1,$value,$value===null?SQLITE3_NULL:SQLITE3_TEXT);}$s->execute();$s->reset();}}$db->exec('COMMIT');}catch(Throwable $e){$db->exec('ROLLBACK');throw $e;}finally{$db->close();}
}

function qxSizeProperty(string $field=''):string {
 $expression='CASE WHEN to_real("spread_m") > 0 AND to_real("spread_m") <= 200 THEN to_real("spread_m") ELSE 2 END * CASE WHEN @map_crs = \'EPSG:3857\' THEN 1 / cos(radians(y(transform($geometry, @layer_crs, \'EPSG:4326\')))) ELSE 1 END';
 $color='';if($field!==''){
  if(!in_array($field,['longevity','stability','tree_health'],true))throw new InvalidArgumentException('Neplatné hodnocení.');
  $test='lower(trim(to_string("'.$field.'")))';$expr='CASE';foreach(qxPalette($field) as $value=>$hex)$expr.=" WHEN ".$test." = '".$value."' THEN '".$hex."'";$expr.=" ELSE '#c8c8c8' END";
  $color='<Option name="fillColor" type="Map"><Option name="active" type="bool" value="true"/><Option name="expression" type="QString" value="'.exXml($expr).'"/><Option name="type" type="int" value="3"/></Option>';
 }
 return '<data_defined_properties><Option type="Map"><Option name="name" type="QString" value=""/><Option name="properties" type="Map">'.$color.'<Option name="size" type="Map"><Option name="active" type="bool" value="true"/><Option name="expression" type="QString" value="'.exXml($expression).'"/><Option name="type" type="int" value="3"/></Option></Option><Option name="type" type="QString" value="collection"/></Option></data_defined_properties>';
}
